[ExtensionOf(classStr(BankPrintTestCheque))]
final class METBankPrintTestCheque_Extension
{
}

Method.Source:
/// <summary>
/// Extension of canRunChequePrintForExtendedFormType
/// </summary>
/// <param name = "_tmpChequePrintout">_tmpChequePrintout</param>
/// <returns>As std. implementation</returns>
protected boolean canRunChequePrintForExtendedFormType(TmpChequePrintout _tmpChequePrintout)
{
    boolean isExtended = next canRunChequePrintForExtendedFormType(_tmpChequePrintout);
    
    isExtended = isExtended || (_tmpChequePrintout.ChequeFormType == ChequeFormType::MET_AU_ANZ);       // MPJ-7141
    isExtended = isExtended || (_tmpChequePrintout.ChequeFormType == ChequeFormType::MET_AU_ANZMulti);  // MPJ_5244_CommunityChestChequeLayout DCP 04/02/2022
    
    return isExtended;
}

/// <summary>
/// Extension of runChequePrintForExtendedChequeFormType
/// </summary>
/// <param name = "_tmpChequePrintout">_tmpChequePrintout</param>
protected void runChequePrintForExtendedChequeFormType(TmpChequePrintout _tmpChequePrintout)
{
    next runChequePrintForExtendedChequeFormType(_tmpChequePrintout);
    
    if (_tmpChequePrintout.ChequeFormType == ChequeFormType::MET_AU_ANZ         // MPJ-7141
    ||  _tmpChequePrintout.ChequeFormType == ChequeFormType::MET_AU_ANZMulti )  // MPJ_5244_CommunityChestChequeLayout DCP 04/02/2022
    {
        Args args = this.getChequePrintArgs(_tmpChequePrintout);
        new MenuFunction(menuitemOutputStr(METCheque_AU_ANZ), MenuItemType::Output).run(args);
    }
}
